"""Generated bytes must not depend on the platform's default newline translation."""

import ast
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]


def _text_writes_without_newline(path: Path) -> list[int]:
    found = []
    for node in ast.walk(ast.parse(path.read_bytes())):
        if not isinstance(node, ast.Call):
            continue
        name = (node.func.attr if isinstance(node.func, ast.Attribute)
                else getattr(node.func, "id", ""))
        keywords = {keyword.arg: keyword.value for keyword in node.keywords}
        if "newline" in keywords:
            continue
        values = [*node.args, keywords.get("mode")]
        modes = [value.value for value in values if isinstance(value, ast.Constant)]
        writes_mode = any(isinstance(mode, str) and "b" not in mode and set(mode) & set("wax")
                          for mode in modes)
        if name == "write_text" or (name in ("open", "fdopen") and writes_mode):
            found.append(node.lineno)
    return found


def test_every_text_write_fixes_its_newline():
    offenders = {
        str(path.relative_to(REPO)): lines
        for root in ("src", "scripts", "studies", "experiments")
        for path in (REPO / root).rglob("*.py")
        if (lines := _text_writes_without_newline(path))
    }
    assert offenders == {}
